import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.doxMM-x8.js";const u=JSON.parse('{"title":"Publish Documentation","description":"","frontmatter":{"docLocale":"en","counterpart":"/getting-started/publish-docs","contentType":"guide","prev":{"text":"Maintain project documentation","link":"/en/guides/documentation"},"next":false},"headers":[],"relativePath":"en/getting-started/publish-docs.md","filePath":"en/getting-started/publish-docs.md"}'),o={name:"en/getting-started/publish-docs.md"};function n(l,e,r,d,c,p){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="publish-documentation" tabindex="-1">Publish Documentation <a class="header-anchor" href="#publish-documentation" aria-label="Permalink to &quot;Publish Documentation&quot;">​</a></h1><p>Goal: publish validated bilingual Lab Word documentation to your GitHub Pages. Source push permission is required; first-time Pages setup requires repository administration. These steps push static artifacts; a local build does not publish.</p><h2 id="_1-check-repository-and-build" tabindex="-1">1. Check Repository And Build <a class="header-anchor" href="#_1-check-repository-and-build" aria-label="Permalink to &quot;1. Check Repository And Build&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/labworld/blob/07736d37ff5c6eb3ffc75c87f67f82e37512ff50/docs/site.json" target="_blank" rel="noreferrer">site.json</a>declares <code>CaiZongyuan/labworld</code> with <code>/labworld/</code> as its default base. Commit and push source first so footer links have an online revision. Markdown and <code>apps/docs/public/</code> are inputs; <code>.generated</code> and VitePress dist are derived.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p>Expect the build checker to verify bilingual pages and internal targets under the base. Unpublished source still renders locally, but GitHub revision links do not establish online availability.</p><h2 id="_2-enable-pages" tabindex="-1">2. Enable Pages <a class="header-anchor" href="#_2-enable-pages" aria-label="Permalink to &quot;2. Enable Pages&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/publish-docs.mjs</span></span></code></pre></div><p>The script commits dist to <code>gh-pages</code> without switching the source branch. In GitHub <strong>Settings → Pages → Build and deployment</strong>, select <strong>Deploy from a branch</strong>, <code>gh-pages</code>, <code>/ (root)</code>.</p><p>After GitHub CLI login:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/publish-docs.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --request-build</span></span></code></pre></div><p>This checks Pages configuration, requests a build, matches the artifact commit and reads the published source revision. A successful push does not establish site availability. If the build is not ready, inspect the reported reason and Pages status.</p><h2 id="_3-later-publication" tabindex="-1">3. Later Publication <a class="header-anchor" href="#_3-later-publication" aria-label="Permalink to &quot;3. Later Publication&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/labworld/blob/07736d37ff5c6eb3ffc75c87f67f82e37512ff50/.github/workflows/ci.yml" target="_blank" rel="noreferrer">CI</a>pushes validated documentation and requests Pages builds after successful <code>main</code> checks. Initial repository setup is still required. Pushes with the Actions token do not trigger Pages builds automatically, so the script requests one explicitly.</p><p>The configured destination is <code>https://caizongyuan.github.io/labworld/</code>; verify actual publication separately. Set <code>DOCS_BASE</code> for custom paths, for example <code>DOCS_BASE=/manual/ pnpm docs:build</code>. Check locale switching, search and navigation before publication.</p><hr><p>Source version：<code>07736d37ff5c</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/07736d37ff5c6eb3ffc75c87f67f82e37512ff50/docs/getting-started/publish-docs.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,17)])])}const b=s(o,[["render",n]]);export{u as __pageData,b as default};
